    ID_RESIDENTE                    NUMBER(10)          NOT NULL,
    ID_USUARIO_REGISTRO             NUMBER(10)          NOT NULL,
    FECHA                           DATE                NOT NULL,
    HORA                            VARCHAR2(8)         NOT NULL,
    PRESION_SISTOLICA               NUMBER(4),
    PRESION_DIASTOLICA              NUMBER(4),
    FRECUENCIA_CARDIACA             NUMBER(4),
    SATURACION_OXIGENO              NUMBER(5,2),
    TEMPERATURA                     NUMBER(4,2),
    GLUCOMETRIA                     NUMBER(5,2),
    PESO_KG                         NUMBER(5,2),
    OBSERVACIONES                   VARCHAR2(500),
    ES_ALERTA_RANGO                 CHAR(1)             DEFAULT 'N' NOT NULL, -- 'S' / 'N'
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_SIGNOS_VITALES PRIMARY KEY (ID),
    CONSTRAINT FK_SMY_SV_RESIDENTE FOREIGN KEY (ID_RESIDENTE) REFERENCES SMY_RESIDENTES (ID) ON DELETE CASCADE,
    CONSTRAINT FK_SMY_SV_USUARIO FOREIGN KEY (ID_USUARIO_REGISTRO) REFERENCES SMY_USUARIOS (ID),
    CONSTRAINT CK_SMY_SV_ALERTA CHECK (ES_ALERTA_RANGO IN ('S', 'N'))
)
